style.css:
@-moz-document domain("roblox.com") {
body {
    background: url("https://imgur.com/a/Dj1nB5g") no-repeat center center fixed !important;
    background-size: cover !important;
    font-family: "Comic Sans MS", cursive, sans-serif !important;
    color: #5c1a72 !important;
  }

  .container-main, .content, .section, .game-page, .navbar {
    background: rgba(255, 255, 255, 0.85) !important;
    border-radius: 12px !important;
    box-shadow: 0 0 15px rgba(255, 105, 180, 0.5) !important;
  }

  button, .btn-primary, .btn-secondary, .btn-control-sm, .btn-growth-md {
    background-color: #ff69b4 !important;
    border: none !important;
    color: white !important;
    border-radius: 10px !important;
    font-weight: bold !important;
  }

  button:hover, .btn-primary:hover {
    background-color: #ff85c1 !important;
  }

  .navbar {
    background-color: rgba(255, 182, 193, 0.9) !important;
    border-bottom: 3px solid #ff69b4 !important;
  }

  a {
    color: #d100a4 !important;
  }

  a:hover {
    color: #ff00aa !important;
    text-decoration: underline !important;
  }

  /* Hide ads */
  .abp, .ad-container, .ads-container, .advertisement {
    display: none !important;
  }
}
